CREATE TEMPORARY VIEW advertise_tracking_item_${grass_region_without_quote} AS 
SELECT
    user_id
    ,campaign_id
    ,ads_id
    ,ads_request_id
    ,item_id
    ,ads_entrance
    ,pricing_type
    ,ads_placement

    ,max(coalesce(cast(target_cir as double)
            , cast(get_json_object(item_json_data, '$.target_cir') as double))
        ) as target_cir
    ,max(cast(if(operation=2,get_json_object(item_json_data, '$.padvv'),null) as double)) as padvv
    -- operation=2: 限制点击
    ,max(cast(if(operation=2,internal.deduction_info.deduction_price,null) as double)) as deduction_price
    ,max(cast(if(operation=2,internal.deduction_info.bidprice,null) as double)) as bid_price
    ,max(
        case when operation = 1 and get_json_object(bid_rerank_trace, '$.bid_voucher_id') is not null
             then item_voucher.display_ads_voucher_label
        end
    ) as display_ads_voucher_label
FROM 
    mkplpaidads_data.dwd_advertise_tracking_item_di__reg_s0_live
WHERE 
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND ads_id > 0
    AND ads_placement != 54 -- exclude video ads 明投
    AND pricing_type != 29 -- exclude 原生发券商品
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW advertise_tracking_item_video_${grass_region_without_quote} AS
SELECT
    user_id
    ,campaign_id
    ,ads_id
    ,ads_request_id
    ,CAST(video_id AS BIGINT) AS video_id
    ,ads_entrance
    ,pricing_type
    ,ads_placement

    ,max(coalesce(cast(target_cir as double)
            , cast(get_json_object(video_json_data, '$.target_cir') as double))
        ) as target_cir
    ,null as padvv
    -- operation：1 impression，14 PRODUCT CLICK ，21 VIDEO VIEW，22 VIDEO_PLAY_TIME，23 VIDEO_PLAY_COMPLETE
    ,max(cast(if(operation=1, internal.cpm_deduction_info.cpm/100000, null) as double)) as deduction_price
    ,max(cast(if(operation=1, bid_price/100000, null) as double)) as bid_price
FROM
    mp_paidads.dwd_request_tracking_video_hi__reg_s0_live
WHERE
    grass_region = ${grass_region}
    -- grass_date & h: SG timezone, filtering for local_date in target region timezone
    AND (
        (
            grass_date = date_timezone_convert(${local_date}, '00', ${grass_region}, 'SG', 'yyyy-MM-dd')
            AND h >= cast(date_timezone_convert(${local_date}, '00', ${grass_region}, 'SG', 'HH') as int)
        )
        OR (
            grass_date = date_timezone_convert(${local_date}, '23', ${grass_region}, 'SG', 'yyyy-MM-dd')
            AND h <= cast(date_timezone_convert(${local_date}, '23', ${grass_region}, 'SG', 'HH') as int)
        )
    )
    AND ads_placement = 54 -- only include video ads 明投
    AND delivery_type = 0 -- 0: 明投，1: 暗投 (目前只有明投)
    AND CAST(video_id AS BIGINT) > 0
GROUP BY
    1,2,3,4,5,6,7,8;

