CREATE TEMPORARY VIEW campaign_roi_${grass_region_without_quote} AS
SELECT
    campaign_id
    ,SUM(broad_order_gmv_amt_usd) / SUM(ads_expenditure_amt_usd) AS campaign_broad_roi_7d
from
    mp_paidads.ads_advertise_mkt_1d__reg_s0_live
where
    grass_date between date_add(date(${local_date}), -6) and date(${local_date})
    and grass_region = ${grass_region}
    and tz_type = 'local'
    and pricing_type = 15
group by 1;

